"use client";
import {useState} from 'react';
import type {SupabaseClient} from '@supabase/supabase-js';
import {AssistantWorkspaceProvider,AssistantTarget,useAssistantWorkspace} from '@/components/assistant-workspace';
import {AssistantConversations} from '@/components/assistant-conversations';
import {AiAssistant} from '@/components/flight-board';
import {ContextualAssistant} from '@/components/contextual-assistant';
import {ModalLayer} from '@/components/modal-layer';
import {assistantHandoffContext} from '@/lib/assistant-handoff';
const entries:unknown[]=[],conversations:unknown[]=[];const recordId='11111111-1111-4111-8111-111111111111';
const client={auth:{getSession:async()=>({data:{session:{access_token:'synthetic'}}})},rpc:async(_name:string,args:{p_action:string;p_payload:Record<string,string>})=>{let data:unknown=[];if(args.p_action==='conversations')data=conversations;if(args.p_action==='create_conversation'){data={id:args.p_payload.id,title:'Relato CHT',created_at:new Date().toISOString(),updated_at:new Date().toISOString()};conversations.push(data);}if(args.p_action==='list')data=entries;if(args.p_action==='append'){data={id:entries.length+1,message:args.p_payload.message,reply:args.p_payload.reply,created_at:new Date().toISOString()};entries.push(data);}return {data,error:null};}} as unknown as SupabaseClient;
function App(){const workspace=useAssistantWorkspace(),[opened,setOpened]=useState(false),[fields,setFields]=useState({title:'Altímetro',description:'Intermitente em voo'});return <main><AssistantTarget id="root" label="Mural" priority={0} revision="1" content={<AssistantConversations direct client={client} user="TEST" onClose={()=>workspace?.close()} renderConversation={(id,back,title)=><AiAssistant conversationId={id} conversationTitle={title} client={client} user="TEST" onClose={back} flights={[]} catalogs={{aircraft:[],bases:[],models:[],users:[]}} onCreate={()=>{}} onOpenTarget={async(ref,conversation)=>{const destination=assistantHandoffContext(ref);if(!destination||!conversation)throw Error('Missing continuation');setOpened(true);workspace?.beginTransfer({...destination,...conversation,nonce:crypto.randomUUID()});}}/>}/>}/>{opened?<ModalLayer><section role="dialog" aria-label="Relato original"><h2>Relato PR-CHT</h2><label>Título<input aria-label="Título do relato" value={fields.title} onChange={e=>setFields({...fields,title:e.target.value})}/></label><output aria-label="Número de conversas">{conversations.length}</output><AssistantTarget id={`record:${recordId}`} label="Relato PR-CHT" revision={JSON.stringify(fields)} content={<ContextualAssistant open context={{kind:'maintenance-draft',id:`record:${recordId}`,record:{id:recordId,revision:1},prefix:'PR-CHT',model:'S92',fields}} client={client} user="TEST" disabled={false} onClose={()=>workspace?.close()} onApply={setFields}/>}/></section></ModalLayer>:null}</main>;}
export default function Page(){return <AssistantWorkspaceProvider><App/></AssistantWorkspaceProvider>;}
